import http from "node:http";

export class LocalStorageShim { ... }

export function installShims({ log }) {
  if (!globalThis.localStorage) globalThis.localStorage = new LocalStorageShim();
  // cookie jar
  const jar = new Map(); // name -> { value, attrs }
  globalThis.__cookieJar = jar;
  const origRequest = http.request;
  http.request = function patched(options, cb) {
    let opts = options;
    if (typeof options === "string" || options instanceof URL) {
      opts = typeof options === "string" ? new URL(options) : options;
    }
    // derive host/port/path for jar keying (single-host harness; keep it simple but explicit)
    let host = "", path = "/", proto = "http";
    if (opts instanceof URL) { host = opts.host; path = opts.pathname; }
    else { host = `${opts.hostname||"localhost"}:${opts.port||(opts.protocol==="https:"?443:80)}`; path = opts.path || "/"; proto = opts.protocol || "http:"; }
    const urlKey = `${proto}//${host}`;
    const cookieHeader = [...jar.entries()].filter(([,c]) => c.value !== null).map(([n,c]) => `${n}=${c.value}`).join("; ");
    const req = origRequest.call(http, options, function(res) {
      const setc = res.headers["set-cookie"] || [];
      for (const line of setc) {
        const [pair, ...attrs] = line.split(";");
        const eq = pair.indexOf("=");
        const name = pair.slice(0, eq).trim();
        const value = pair.slice(eq + 1).trim();
        const lower = attrs.map(a=>a.trim().toLowerCase());
        const del = lower.some(a => a.startsWith("max-age=0") || a === "expires=thu, 01 jan 1970 00:00:00 gmt");
        if (del || value === "") jar.set(name, { value: null });
        else jar.set(name, { value });
      }
      cb(res);
    });
    if (cookieHeader) req.setHeader("Cookie", cookieHeader);
    return req;
  };
  return jar;
}
```
Concern: axios/follow-redirects might call http.request with (options) where options contains a callback via `options.agent`... standard single-object call. Also axios node adapter in v1.x: it uses `http.request`? Let me double check axios 1.x: `lib/adapters/http.js` builds `options` and calls `transport.request(options, function handleResponse(res){...})` where transport = http or https module or follow-redirects wrapper. follow-redirects wrapper: `wrappedProtocol.request = wrapRequest(nativeProtocol)` — nativeProtocol captured as MODULE OBJECT (`require("http")`) — wrapRequest calls `nativeProtocol.request.call(...)`. Since we patch the module object's `request` property, follow-redirects gets our patched function. 

But careful: patch `http.request` — follow-redirects calls it with `.call(this.input, options, responseHandler)` — fine. Also, our patched fn receives (options, cb). Also axios may pass callback as third arg? No.

setHeader after creation: allowed before headers flushed. Node flushes headers when the request is about to be sent (on connect). Immediate setHeader OK.

One risk: `http.request` also used by other things (npm? no—runtime only). Fine.

